const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const http = require('node:http');
const assert = require('node:assert/strict');
const { promisify } = require('node:util');
const run = promisify(require('node:child_process').execFile);
const root = process.cwd();
require(path.join(root, 'test/test-env')).applyTestEnv();
const home = fs.mkdtempSync(path.join(os.tmpdir(), 'r11-proof-'));
Object.assign(process.env, { HOME: home, TMUX_TMPDIR: path.join(home, 'tmux'), PI_DISH_INDEX_SYNC_BUDGET: '1000' });
fs.mkdirSync(process.env.TMUX_TMPDIR);
const native = '2026-09-05T09-07-03-291Z_01a070d2-43fb-7360-aaba-a4ddf8d1deb0';
const route = '~sk1_' + Buffer.from(JSON.stringify(['omp', native])).toString('base64url');
const shadowed = '~sk1_' + Buffer.from(JSON.stringify(['omp', 'shadowed'])).toString('base64url');
const fixtures = [['omp', native, 'Canonical OMP'], ['pi', 'route-hit', 'Exact route'], ['omp', 'route-hit', 'Shadowed alias'], ['omp', 'alias-hit', 'Exact alias'], ['pi', 'alias-hit-long', 'Shadowed prefix'], ['pi', 'twin-a', 'Twin A'], ['pi', 'twin-b', 'Twin B'], ['omp', 'shadowed', 'Full alias retained'], ['omp', 'shadowed-long', 'Longer peer alias']];
for (const [harness, id, title] of fixtures) {
  const dir = path.join(home, `.${harness}`, 'agent/sessions/project');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, id + '.jsonl'), [
    { type: 'session', version: 3, id, cwd: home, timestamp: '2026-09-05T09:07:03.291Z' },
    { type: 'session_info', name: title },
    { type: 'message', id: 'u1', message: { role: 'user', content: [{ type: 'text', text: title }], timestamp: '2026-09-05T09:07:04.000Z' } },
  ].map(JSON.stringify).join('\n') + '\n');
}
const installed = path.join(home, 'standalone/skills');
fs.mkdirSync(path.join(installed, 'lib'), { recursive: true });
fs.copyFileSync(path.join(root, 'skills/lib/pi-dish-client.js'), path.join(installed, 'lib/pi-dish-client.js'));
for (const skill of ['pi-dish-sessions', 'pi-dish-comments', 'pi-dish-pages']) {
  fs.mkdirSync(path.join(installed, skill, 'scripts'), { recursive: true });
  fs.copyFileSync(path.join(root, 'skills', skill, 'scripts', skill + '.js'), path.join(installed, skill, 'scripts', skill + '.js'));
  fs.mkdirSync(path.join(home, '.pi/agent/skills'), { recursive: true });
  fs.symlinkSync(path.join(installed, skill), path.join(home, '.pi/agent/skills', skill));
}
const cli = path.join(home, '.pi/agent/skills/pi-dish-sessions/scripts/pi-dish-sessions.js');
const server = require(path.join(root, 'server'));
let legacy;
async function main() {
  if (!server.listening) await new Promise(resolve => server.once('listening', resolve));
  const base = `http://127.0.0.1:${server.address().port}`;
  let list;
  for (let i = 0; i < 100; i++) {
    list = await (await fetch(base + '/api/sessions')).json();
    if (!list.indexing && list.previous.length === fixtures.length) break;
    await new Promise(resolve => setTimeout(resolve, 50));
  }
  assert.equal(list.previous.length, fixtures.length);
  const identity = await (await fetch(base + '/api/host')).json();
  let selectedHarness;
  legacy = http.createServer(async (req, res) => {
    if (req.url === '/api/harnesses') {
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify({ harnesses: [{ id: 'omp', available: true }] }));
    }
    if (req.url === '/api/sessions/new' && req.method === 'POST') {
      let body = ''; for await (const chunk of req) body += chunk;
      selectedHarness = JSON.parse(body).harness;
      res.setHeader('Content-Type', 'application/json');
      return res.end(JSON.stringify({ sessionId: 'isolated-admission-fixture' }));
    }
    const response = await fetch(base + req.url);
    const data = await response.json();
    if (req.url === '/api/hosts') for (const host of data.hosts) host.capabilities = {};
    res.writeHead(response.status, { 'content-type': 'application/json' });
    res.end(JSON.stringify(data));
  });
  await new Promise(resolve => legacy.listen(0, '127.0.0.1', resolve));
  const legacyBase = `http://127.0.0.1:${legacy.address().port}`;
  const outputs = [];
  for (const endpoint of [base, legacyBase]) {
    const invoke = args => run(process.execPath, [cli, ...args, '--url', endpoint], { env: process.env, cwd: home });
    for (const [ref, expected] of [['01a070d2', route], ['route-hit', 'route-hit'], ['alias-hit', '~sk1_' + Buffer.from(JSON.stringify(['omp', 'alias-hit'])).toString('base64url')], [`${identity.hostId}:${route}`, route], ['self/01a070d2', route], ['shadowed', shadowed]]) {
      const resolved = JSON.parse((await invoke(['resolve', ref, '--json'])).stdout);
      assert.equal(resolved.id, expected);
      outputs.push({ endpoint: endpoint === base ? 'product' : 'legacy-fallback', ref, id: resolved.id });
    }
    await assert.rejects(invoke(['resolve', 'twin-']), e => e.code === 1 && /twin-a/.test(e.stderr) && /twin-b/.test(e.stderr));
    await assert.rejects(invoke(['resolve', `${identity.hostId}:01a070d2`]), e => e.code === 1 && /Session not found/.test(e.stderr));
    await assert.rejects(invoke(['resolve', '']), e => e.code === 1 && /session ref/.test(e.stderr));
    const printed = (await invoke(['list'])).stdout;
    assert.ok(printed.includes(endpoint === base ? '01a070d2\t' : route + '\t'));
    assert.ok(printed.includes(endpoint === base ? 'shadowed\t' : shadowed + '\t'));
  }
  const missingNative = '~sk1_' + Buffer.from(JSON.stringify(['omp'])).toString('base64url');
  const inherited = JSON.parse((await run(process.execPath, [cli, 'spawn', '--session', missingNative, '--no-wait', '--json', '--url', legacyBase], { env: process.env, cwd: home })).stdout);
  assert.equal(inherited.harness, 'omp');
  assert.equal(selectedHarness, 'omp');
  assert.equal((await fetch(base + '/api/sessions/resolve?id=twin-')).status, 409);
  const comments = path.join(home, '.pi/agent/skills/pi-dish-comments/scripts/pi-dish-comments.js');
  assert.equal(JSON.parse((await run(process.execPath, [comments, 'count', '--session', route, '--url', base, '--json'], { env: process.env, cwd: home })).stdout).total, 0);
  const pages = path.join(home, '.pi/agent/skills/pi-dish-pages/scripts/pi-dish-pages.js');
  const html = path.join(home, 'proof.html');
  fs.writeFileSync(html, '<h1>R11 isolated publication</h1>');
  const published = JSON.parse((await run(process.execPath, [pages, 'publish', html, '--session', route, '--url', base, '--json'], { env: process.env, cwd: home })).stdout);
  assert.equal((await fetch(base + '/page/' + published.token)).status, 200);
  const result = { base, legacyBase, home, route, standalone: installed, assertions: '12 resolutions including shadowed full alias, two ambiguity exits, two exact-only misses, two empty-ref errors, two list policies including shadowed alias, missing-native CLI spawn harness inference against admission fixture (no native process launched), HTTP 409, three standalone installed CLI loaders', outputs };
  fs.writeFileSync('/tmp/r11-runtime-result.json', JSON.stringify(result, null, 2));
  console.log('R11_READY ' + JSON.stringify(result));
}
process.on('SIGTERM', () => { legacy?.close(); server.close(); fs.rmSync(home, { recursive: true, force: true }); setTimeout(() => process.exit(0), 200).unref(); });
main().catch(error => { console.error(error); process.exitCode = 1; legacy?.close(); server.close(); });
